printf("Median mismatch at last position : %.2f ns/op\n", $l);
printf("Ratio (late/early)               : %.2fx\n\n", $l / $e);

echo "=== Length 32 bytes, the actual Grav nonce length, md5 hex output ===\n";
[$e2, $l2] = runExperiment(32, 200000, 21);
